package source

import (
	_ "embed"
	"encoding/json"
	"errors"
	"io/fs"
	"log/slog"
	"maps"
	"os"
	"regexp"
	"slices"
	"strconv"
	"strings"
	"sync"
	"unicode"
	"unicode/utf8"

	"github.com/TheAbubakrAbu/501st-War-Room/internal/atomicfile"
)

// planets.json is generated by `go run ./tools/planets` (spec 5.3).
//
//go:embed planets.json
var embedded []byte

// PlanetName is a planet's display name and sector.
type PlanetName struct {
	Name   string `json:"name"`
	Sector string `json:"sector"`
}

type namedPlanet struct {
	Index int `json:"index"`
	PlanetName
}

// Names maps planet indexes to names. It starts from the embedded file,
// lays the cache file over it, and saves to the cache when a round brings
// new names. It is safe for concurrent use.
type Names struct {
	mu    sync.RWMutex
	byIdx map[int]PlanetName
	path  string
	log   *slog.Logger
}

var (
	embedOnce  sync.Once
	embedNames map[int]PlanetName
	embedUpper map[string]string // upper-case name -> display name
)

func loadEmbedded() {
	embedOnce.Do(func() {
		m, err := parseNames(embedded)
		if err != nil {
			panic("source: embedded planets.json: " + err.Error())
		}
		embedNames = m
		embedUpper = make(map[string]string, len(m))
		for _, n := range m {
			embedUpper[strings.ToUpper(n.Name)] = n.Name
		}
	})
}

func parseNames(b []byte) (map[int]PlanetName, error) {
	var list []namedPlanet
	if err := json.Unmarshal(b, &list); err != nil {
		return nil, err
	}
	m := make(map[int]PlanetName, len(list))
	for _, p := range list {
		m[p.Index] = p.PlanetName
	}
	return m, nil
}

// EncodeNames writes names in the embedded file's format: a JSON array
// sorted by index, two-space indent.
func EncodeNames(m map[int]PlanetName) []byte {
	list := make([]namedPlanet, 0, len(m))
	for _, i := range slices.Sorted(maps.Keys(m)) {
		list = append(list, namedPlanet{Index: i, PlanetName: m[i]})
	}
	b, _ := json.MarshalIndent(list, "", "  ")
	return append(b, '\n')
}

// LoadNames returns the embedded names, with the cache file at cachePath
// laid over them when it exists and parses. An empty cachePath never reads
// or saves.
func LoadNames(cachePath string, log *slog.Logger) *Names {
	loadEmbedded()
	n := &Names{byIdx: maps.Clone(embedNames), path: cachePath, log: log}
	if cachePath == "" {
		return n
	}
	b, err := os.ReadFile(cachePath)
	switch {
	case errors.Is(err, fs.ErrNotExist):
	case err != nil:
		log.Warn("planet names cache unreadable, using built-in names", "path", cachePath, "err", err)
	default:
		m, err := parseNames(b)
		if err != nil || len(m) == 0 {
			log.Warn("planet names cache broken, using built-in names", "path", cachePath, "err", err)
			break
		}
		maps.Copy(n.byIdx, m)
	}
	return n
}

// Get returns the name for index, or "Planet <index>" when there is none.
func (n *Names) Get(index int) PlanetName {
	n.mu.RLock()
	defer n.mu.RUnlock()
	if p, ok := n.byIdx[index]; ok {
		return p
	}
	return PlanetName{Name: "Planet " + strconv.Itoa(index)}
}

// Update merges m into the names and saves them when anything changed. A
// failed save logs a warning; the names in memory still change.
func (n *Names) Update(m map[int]PlanetName) {
	n.mu.Lock()
	changed := false
	for i, p := range m {
		if n.byIdx[i] != p {
			n.byIdx[i] = p
			changed = true
		}
	}
	var data []byte
	if changed && n.path != "" {
		data = EncodeNames(n.byIdx)
	}
	n.mu.Unlock()
	if data == nil {
		return
	}
	if err := atomicfile.Write(n.path, data); err != nil {
		n.log.Warn("could not save planet names", "path", n.path, "err", err)
	}
}

// Display turns an API name (all capitals) into the display name: the
// embedded file's casing when it knows the name, else TitleCase.
func Display(apiName string) string {
	loadEmbedded()
	if name, ok := embedUpper[strings.ToUpper(strings.TrimSpace(apiName))]; ok {
		return name
	}
	return TitleCase(apiName)
}

var roman = regexp.MustCompile(`^(X{0,3})(IX|IV|V?I{0,3})$`)

// TitleCase capitalizes each word, keeping Roman numerals upper case:
// "NEW PLANET IV" becomes "New Planet IV", "CHARBAL-VII" "Charbal-VII".
func TitleCase(s string) string {
	words := strings.Fields(s)
	for i, w := range words {
		parts := strings.Split(w, "-")
		for j, p := range parts {
			parts[j] = titleWord(p)
		}
		words[i] = strings.Join(parts, "-")
	}
	return strings.Join(words, " ")
}

func titleWord(p string) string {
	up := strings.ToUpper(p)
	if p != "" && roman.MatchString(up) {
		return up
	}
	r, size := utf8.DecodeRuneInString(p)
	if r == utf8.RuneError {
		return p
	}
	return string(unicode.ToUpper(r)) + strings.ToLower(p[size:])
}
